import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.CqGPl1zp.js";const l="/newx-doc/assets/%E6%B5%81%E7%A8%8B%E7%B1%BB%E5%9E%8B.BKg7iYo7.png",s="/newx-doc/assets/%E9%92%89%E9%92%89.Be2if9lq.png",o="/newx-doc/assets/%E8%8A%82%E7%82%B9%E7%B1%BB%E5%9E%8B.CG9FXzMW.png",n="/newx-doc/assets/%E5%8F%91%E8%B5%B7%E4%BA%BA.CZJP8iDl.png",p="/newx-doc/assets/%E5%AE%A1%E6%89%B9%E4%BA%BA.3oHs4sC3.png",c="/newx-doc/assets/%E5%AE%A1%E6%89%B9%E4%BA%BA-%E7%9B%91%E5%90%AC%E5%99%A8.toXQiRUb.png",E="/newx-doc/assets/%E5%8A%9E%E7%90%86%E4%BA%BA.IooyaZBf.png",d="/newx-doc/assets/%E6%8A%84%E9%80%81%E4%BA%BA.C_xAB5V-.png",h="/newx-doc/assets/%E6%9D%A1%E4%BB%B6%E5%88%86%E6%94%AF.DfAaz0jP.png",m="/newx-doc/assets/%E5%B9%B6%E8%A1%8C%E5%88%86%E6%94%AF.C-INFmMi.png",_="/newx-doc/assets/%E5%8C%85%E5%AE%B9%E5%88%86%E6%94%AF.BmUo8shu.png",u="/newx-doc/assets/%E8%B7%AF%E7%94%B1%E5%88%86%E6%94%AF.kDquJ5LH.png",B="/newx-doc/assets/%E5%AD%90%E6%B5%81%E7%A8%8B.W2X8j0hb.png",g="/newx-doc/assets/%E5%BB%B6%E8%BF%9F%E5%99%A8.DjpdFKHk.png",A="/newx-doc/assets/%E8%A7%A6%E5%8F%91%E5%99%A8.C0CbUCoz.png",M=JSON.parse('{"title":"流程设计器（钉钉、飞书）","description":"","frontmatter":{},"headers":[],"relativePath":"bpm/model-designer-dingding.md","filePath":"bpm/model-designer-dingding.md","lastUpdated":null}'),b={name:"bpm/model-designer-dingding.md"};function f(P,a,x,w,q,k){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="流程设计器-钉钉、飞书" tabindex="-1">流程设计器（钉钉、飞书） <a class="header-anchor" href="#流程设计器-钉钉、飞书" aria-label="Permalink to &quot;流程设计器（钉钉、飞书）&quot;">​</a></h1><p>SIMPLE 设计器，对标钉钉、飞书等平台的流程设计器，界面简洁，易上手，适合大多数常见的审批场景。</p><p>只需要在新建/修改流程模型时，选择 “SIMPLE” 设计器即可。如下图所示：</p><p><img src="'+l+'" alt="流程类型"></p><p>它的实现原理比较简单，分成 2 阶段：</p><p><img src="'+s+'" alt="钉钉"></p><ul><li>流程「设计」阶段：通过拖拽组件，配置节点属性，生成 JSON 格式的流程定义数据，保存到数据库，可见前端 <a href="https://github.com/yudaocode/yudao-ui-admin-vue3/tree/master/src/components/SimpleProcessDesignerV2" target="_blank" rel="noreferrer">SimpleProcessDesignerV2</a> 组件</li><li>流程「保存」阶段：后端将 JSON 格式的流程定义数据，转换成 BPMN XML 格式，保存到 Flowable 引擎，可见后端 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-bpm/src/main/java/cn/iocoder/yudao/module/bpm/framework/flowable/core/util/SimpleModelUtils.java" target="_blank" rel="noreferrer">SimpleModelUtils</a> 工具</li></ul><p>也因此，SIMPLE 设计器是 BPMN 设计器的一个「子集」，支持的节点类型、属性配置，都比 BPMN 设计器少，适合简单、中等复杂度的流程设计。一般情况下，默认使用 SIMPLE 设计器即可；如果遇到复杂的流程设计需求，再切换到 BPMN 设计器进行设计。</p><hr><p>下面，我们来看看 SIMPLE 设计器有哪些节点类型。</p><p><img src="'+o+'" alt="节点类型"></p><p>ps：再开始之前，希望你已经阅读过 <a href="./model-designer-bpmn">《11.流程设计器（BPMN）》</a> 文档，相同的内容，就不再赘述。</p><h2 id="_1-操作节点" tabindex="-1">1. 操作节点 <a class="header-anchor" href="#_1-操作节点" aria-label="Permalink to &quot;1. 操作节点&quot;">​</a></h2><p>包括发起人、审批人、办理人、抄送人四种节点。</p><h3 id="_1-1-发起人" tabindex="-1">1.1 发起人 <a class="header-anchor" href="#_1-1-发起人" aria-label="Permalink to &quot;1.1 发起人&quot;">​</a></h3><p>发起人，流程默认的首个节点是发起人节点，用于配置表单字段权限。如下图所示：</p><p><img src="'+n+'" alt="发起人"></p><h3 id="_1-2-审批人" tabindex="-1">1.2 审批人 <a class="header-anchor" href="#_1-2-审批人" aria-label="Permalink to &quot;1.2 审批人&quot;">​</a></h3><p>相关文档：</p><ul><li><a href="https://www.feishu.cn/hc/zh-CN/articles/360036163653-%E7%AE%A1%E7%90%86%E5%91%98%E8%AE%BE%E8%AE%A1%E5%AE%A1%E6%89%B9%E6%B5%81%E7%A8%8B#tabs0%7Clineguid-p5mRd" target="_blank" rel="noreferrer">《飞书使用手册 —— 管理员设计审批流程》</a></li></ul><p>审批人，基于 BPMN 设计器的用户任务节点，用于配置审批人的规则。如下图所示：</p><p><img src="'+p+'" alt="审批人"></p><ul><li>审批人设置：设置审批人是谁，包括指定、表单、发起人自己以及主管等等</li><li>表单权限：设置审批人看到的表单权限，包括只读、编辑和隐藏</li><li>操作权限：设置审批人可以执行的操作，包括通过、拒绝、加签、转办等等</li></ul><p>比较特殊的是监听器，使用类似 Postman 交互的 HTTP 请求配置方式，支持配置前置通知、后置通知。如下图所示：</p><p><img src="'+c+'" alt="监听器"></p><h3 id="_1-3-办理人" tabindex="-1">1.3 办理人 <a class="header-anchor" href="#_1-3-办理人" aria-label="Permalink to &quot;1.3 办理人&quot;">​</a></h3><p>相关文档：</p><ul><li><a href="https://www.feishu.cn/hc/zh-CN/articles/144478657626-%E7%AE%A1%E7%90%86%E5%91%98%E8%AE%BE%E7%BD%AE%E5%8A%9E%E7%90%86%E4%BA%BA%E8%8A%82%E7%82%B9" target="_blank" rel="noreferrer">《飞书使用手册 —— 管理员设置办理人节点》</a></li><li><a href="https://alidocs.dingtalk.com/i/p/L4BYmaE53pwmNA8EYRBGveyaLJ3pKmDA" target="_blank" rel="noreferrer">《钉钉使用手册 —— 设置办理人》</a></li></ul><p>办理人，是特殊的“审批人”，适用于流程中存在某个节点不需要审批，但需要人员执行相关业务操作的情况，例如财务打款、处理盖章、文件归档等。如下图所示：</p><p><img src="'+E+'" alt="办理人"></p><p>相比审批人来说，它少了一些配置项，例如操作权限、审批人拒绝时等。</p><h3 id="_1-4-抄送人" tabindex="-1">1.4 抄送人 <a class="header-anchor" href="#_1-4-抄送人" aria-label="Permalink to &quot;1.4 抄送人&quot;">​</a></h3><p>抄送人，不进行任何操作，仅接收抄送通知给相关人。如下图所示：</p><p><img src="'+d+'" alt="抄送人"></p><ul><li>抄送人设置：设置抄送人是谁，包括指定、表单、发起人自己以及主管等等</li><li>表单权限：设置抄送人看到的表单权限，包括只读、编辑和隐藏</li></ul><h2 id="_2-分支节点" tabindex="-1">2. 分支节点 <a class="header-anchor" href="#_2-分支节点" aria-label="Permalink to &quot;2. 分支节点&quot;">​</a></h2><p>包括条件分支、并行分支、包容分支、路由分支四种节点。</p><h3 id="_2-1-条件分支" tabindex="-1">2.1 条件分支 <a class="header-anchor" href="#_2-1-条件分支" aria-label="Permalink to &quot;2.1 条件分支&quot;">​</a></h3><p>相关文档：</p><ul><li><a href="https://www.feishu.cn/hc/zh-CN/articles/360045139814-%E7%AE%A1%E7%90%86%E5%91%98%E8%AE%BE%E7%BD%AE%E6%9D%A1%E4%BB%B6%E5%88%86%E6%94%AF" target="_blank" rel="noreferrer">《飞书使用手册 —— 管理员设置条件分支》</a></li><li><a href="https://alidocs.dingtalk.com/i/p/L4BYmaE53pwmNA8EYRBGvey6baxaAmDA" target="_blank" rel="noreferrer">《钉钉使用手册 —— 设置条件分支 》</a></li></ul><p>条件分支，基于 BPMN 设计器的 exclusiveGateway 排它网关节点，用于根据条件选择一个分支执行。如下图所示：</p><p><img src="'+h+'" alt="条件分支"></p><ul><li>根据条件，从左到右逐个匹配，仅执行第一个匹配到的分支</li><li>都不匹配的情况下，则执行最后一个默认分支（其它情况）</li></ul><h3 id="_2-2-并行分支" tabindex="-1">2.2 并行分支 <a class="header-anchor" href="#_2-2-并行分支" aria-label="Permalink to &quot;2.2 并行分支&quot;">​</a></h3><p>相关文档：</p><p>并行分支，基于 BPMN 设计器的 inclusiveGateway 包容网关（<code>条件表达式结果设置为 true</code>）节点，用于将流程分成多条分支，所有分支都会执行。如下图所示：</p><p><img src="'+m+'" alt="并行分支"></p><ul><li>无条件判断，所有分支都会执行</li><li>所有分支执行完毕，才能进入下一个节点</li></ul><h3 id="_2-3-包容分支" tabindex="-1">2.3 包容分支 <a class="header-anchor" href="#_2-3-包容分支" aria-label="Permalink to &quot;2.3 包容分支&quot;">​</a></h3><p>包容分支，基于 BPMN 设计器的 inclusiveGateway 包容网关节点，用于根据条件选择多条分支执行。如下图所示：</p><p><img src="'+_+'" alt="包容分支"></p><ul><li>根据条件，匹配的都执行</li><li>都不匹配的情况下，则执行最后一个默认分支（其它情况）</li></ul><h3 id="_2-4-路由分支" tabindex="-1">2.4 路由分支 <a class="header-anchor" href="#_2-4-路由分支" aria-label="Permalink to &quot;2.4 路由分支&quot;">​</a></h3><p>路由分支，基于 BPMN 设计器的 exclusiveGateway 排它网关节点，根据条件配置，实现节点自动跳转。如下图所示：</p><p><img src="'+u+'" alt="路由分支"></p><p>它和上面的三种分支，有一个本质的区别：直接跳转到指定节点，而不是继续往下执行。</p><h2 id="_3-其它节点" tabindex="-1">3. 其它节点 <a class="header-anchor" href="#_3-其它节点" aria-label="Permalink to &quot;3. 其它节点&quot;">​</a></h2><p>包括子流程、延迟器、触发器三种节点。</p><h3 id="_3-1-子流程" tabindex="-1">3.1 子流程 <a class="header-anchor" href="#_3-1-子流程" aria-label="Permalink to &quot;3.1 子流程&quot;">​</a></h3><p>子流程，基于 BPMN 设计器的 callActivity 调用子流程节点，用于实现主流程调用子流程的功能。如下图所示：</p><p><img src="'+B+'" alt="子流程"></p><p>子流程的使用场景（<strong>代码复用</strong>）：将共性的流程抽取出来，作为独立流程被其他流程引入使用</p><p>子流程的执行模式（通过 <strong>“是否异步”</strong> 开关）：</p><ul><li><strong>同步</strong>子流程：主流程等待子流程执行完成后，再继续向后执行</li><li><strong>异步</strong>子流程：主流程不等待子流程执行完成，直接完成当前节点继续向后执行</li></ul><h3 id="_3-2-延迟器" tabindex="-1">3.2 延迟器 <a class="header-anchor" href="#_3-2-延迟器" aria-label="Permalink to &quot;3.2 延迟器&quot;">​</a></h3><p>延迟器，基于 BPMN 设计器的 timerEventDefinition 定时事件节点，用于实现流程等待一段时间再执行的功能。如下图所示：</p><p><img src="'+g+'" alt="延迟器"></p><h3 id="_3-3-触发器" tabindex="-1">3.3 触发器 <a class="header-anchor" href="#_3-3-触发器" aria-label="Permalink to &quot;3.3 触发器&quot;">​</a></h3><p>触发器，基于 BPMN 设计器的 receiveTask 接收任务节点，用于实现执行到该节点，触发 HTTP 请求、HTTP 回调、更新数据、删除数据等功能。如下图所示：</p><p><img src="'+A+'" alt="触发器"></p>',70)])])}const D=e(b,[["render",f]]);export{M as __pageData,D as default};
